/**
 * The proxy: forwards `/qwen/v1/*` and `/clef/*` to the platform's relay with a fresh inference token, each request
 * signed with an Ed25519 key that lives only in this process, and streams the answer back as it arrives (SSE and
 * keepalives included). With a team key (deployments without GitHub sign-in) it sends that key instead.
 */
export function modelsProxy({ api, key, port = MODELS_PORT, models = modelsOn(), log = () => {}, now = Date.now }) {
  const personal = key.startsWith("atp_")
  let current = null
  let minting = null
  let timer = null

  async function mint() {
    const pair = generateKeyPairSync("ed25519")
    const publicKey = pair.publicKey.export({ format: "jwk" }).x
    const response = await send(api, "POST", "/v1/me/inference-token", { key, body: { public_key: publicKey } })
    if (!response.ok) throw await responseError(response)
    const minted = await response.json()
    current = { token: minted.token, expiresAt: minted.expires_at, privateKey: pair.privateKey }
    clearTimeout(timer)
    timer = setTimeout(
      () => rotate().catch((error) => log(`atira: could not rotate the inference token: ${error.message}`)),
      Math.max(1_000, minted.expires_at - ROTATE_BEFORE_MS - now()),
    )
    timer.unref?.()
    return current
  }

  /** One mint at a time: concurrent calls wait for the same one. */
  function rotate() {
    minting ??= mint().finally(() => {
      minting = null
    })
    return minting
  }

  async function credential(force) {
    if (!personal) return null
    if (force || !current || now() >= current.expiresAt - ROTATE_BEFORE_MS) return rotate()
    return current
  }

  function headersFor(request, url, body, held) {
    const headers = new Headers()
    for (const [name, value] of Object.entries(request.headers))
      if (!DROPPED.test(name) && value !== undefined) headers.set(name, Array.isArray(value) ? value.join(", ") : value)
    headers.set("user-agent", `${USER_AGENT} ${PROXY_CLIENT}`)
    headers.set("x-atira-client", PROXY_CLIENT)
    if (!held) {
      headers.set("authorization", `Bearer ${key}`)
      return headers
    }
    const ts = String(now())
    const nonce = randomBytes(18).toString("base64url")
    const text = `${ts}\n${nonce}\n${request.method.toUpperCase()}\n${url.pathname}${url.search}\n${createHash("sha256").update(body).digest("hex")}`
    headers.set("authorization", `Bearer ${held.token}`)
    headers.set("x-atira-ts", ts)
    headers.set("x-atira-nonce", nonce)
    headers.set("x-atira-sig", sign(null, Buffer.from(text), held.privateKey).toString("base64url"))
    return headers
  }

  const fail = (response, status, message) => {
    if (response.headersSent) return response.destroy()
    response.writeHead(status, { "content-type": "application/json" })
    response.end(JSON.stringify({ type: "error", error: { type: "api_error", message } }))
  }

  async function handle(request, response) {
    const local = new URL(request.url ?? "/", "http://127.0.0.1")
    const route = models.find((entry) => local.pathname === entry.local || local.pathname.startsWith(`${entry.local}/`))
    if (!route)
      return fail(response, 404, `Unknown path. Use ${models.map((entry) => `${entry.local}/...`).join(" or ")}.`)
    const chunks = []
    let size = 0
    for await (const chunk of request) {
      size += chunk.length
      if (size > MAX_MODEL_BODY) return fail(response, 413, "The request body is over 32 MB.")
      chunks.push(chunk)
    }
    const body = Buffer.concat(chunks)
    const url = new URL(`${api}${route.relay}${local.pathname.slice(route.local.length)}${local.search}`)
    const abort = new AbortController()
    response.on("close", () => abort.abort())
    const call = async (force) => {
      const held = await credential(force)
      return fetch(url, {
        method: request.method,
        headers: headersFor(request, url, body, held),
        body: ["GET", "HEAD"].includes(request.method ?? "GET") ? undefined : body,
        redirect: "manual",
        signal: abort.signal,
      })
    }
    let upstream
    try {
      upstream = await call(false)
      // the token was retired (another proxy minted past the cap, or the clock moved): once more with a fresh one
      if (upstream.status === 401 && personal) {
        await upstream.body?.cancel()
        upstream = await call(true)
      }
    } catch (error) {
      if (abort.signal.aborted) return
      if (error instanceof CliError) return fail(response, error.status ?? 502, error.message)
      return fail(response, 502, `Cannot reach ${api}: ${error.cause?.message ?? error.message}`)
    }
    const headers = {}
    for (const [name, value] of upstream.headers) if (!RESPONSE_DROPPED.test(name)) headers[name] = value
    response.writeHead(upstream.status, headers)
    response.flushHeaders()
    if (!upstream.body) return response.end()
    try {
      for await (const chunk of upstream.body) response.write(chunk)
      response.end()
    } catch {
      response.destroy()
    }
  }

  const server = createServer((request, response) => {
    handle(request, response).catch((error) => fail(response, 500, error.message))
  })
  return {
    server,
    /** Mints the first token (so a missing sign-in fails here), then listens on 127.0.0.1 only. */
    async start() {
      await credential(false)
      await new Promise((done, failed) => {
        server.once("error", failed)
        server.listen(port, "127.0.0.1", done)
      })
      return server.address().port
    },
    close() {
      clearTimeout(timer)
      server.closeAllConnections?.()
      return new Promise((done) => server.close(() => done()))
    },
  }
}

async function models({ args, options, json }) {
  if (args[0] !== "proxy") throw new CliError(EXIT.usage, "Usage: atira models proxy [--port <port>]")
  const on = modelsOn()
  if (!on.length) throw new CliError(EXIT.notFound, "This platform has no free models on.")
